const e="Adult Anxiety & Depression | Michelle Barratt Psychology",t="Adult anxiety and depression treatment in Brisbane and online Australia-wide.",i='<!--$--><section class="bg-gradient-to-br from-plum to-rose text-white"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20"><div><nav aria-label="Breadcrumb" class="mb-6"><ol class="flex flex-wrap items-center gap-2 text-[12px] uppercase tracking-[0.14em] text-white/75"><li><a class="hover:text-white" href="/">Home</a></li><li aria-hidden="true"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3 w-3"><path d="m9 18 6-6-6-6"></path></svg></li><li><a class="hover:text-white active" href="/therapy-services" data-status="active" aria-current="page">Therapy Services</a></li><li aria-hidden="true"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3 w-3"><path d="m9 18 6-6-6-6"></path></svg></li><li class="text-white" aria-current="page">Adult Anxiety &amp; Depression</li></ol></nav><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-white/85 mb-3">Individuals &amp; Adult Therapy</p><h1 class="text-white text-[32px] md:text-[44px] font-semibold leading-[1.08] max-w-3xl">Adult Therapy for Anxiety &amp; Depression</h1><div class="h-[3px] w-16 bg-sun my-5" aria-hidden="true"></div><div class="max-w-2xl text-[16px] md:text-[17px] text-white/95 space-y-3"><p>Adult anxiety and depression treatment in Brisbane and online Australia-wide.</p><p>Our psychologists use evidence-based therapies, including Cognitive Behavioural Therapy (CBT) and Acceptance and Commitment Therapy (ACT), to help manage anxiety, improve mood, strengthen coping skills, and support sustainable mental health and wellbeing.</p></div><div class="mt-6 flex flex-wrap gap-3"><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-white text-plum hover:bg-blush " href="/contact">Contact Us</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 border border-white/70 text-white hover:bg-white/10 " href="/practitioners">See Practitioners</a></div></div></div></section><section class="bg-soft !py-0"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="py-14 md:py-16"><img src="https://michellebarrattpsychology.com.au/wp-content/uploads/2022/11/adult-therapy.jpg" alt="Adult Therapy" class="w-full aspect-[16/9] max-h-[520px] object-cover rounded border border-lilac"/></div></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Adult Therapy for Anxiety and Depression</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Adult Therapy for Anxiety and Depression offers evidence-based treatment to reduce persistent worry, low mood, panic, and the daily impact of anxiety and depression. Therapy focuses on practical skills for emotional regulation, cognitive restructuring, behavioural activation, and relapse prevention so you can regain energy, clarity, and purpose. Michelle Barratt Psychology (MBP) provides in-person therapy across Brisbane and flexible online therapy options Australia-wide, ensuring your healing journey remains consistent and accessible.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">How does MBP support therapy for Adult Anxiety and Depression?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Michelle Barratt Psychology Administrative Services (MBP) provides a clinically informed administrative hub that connects you with the right Brisbane psychologists and allied health professionals .</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Drawing on 12 years of clinical experience, MBP combines professional insight with efficient administrative support to ensure every enquiry is handled with care, sensitivity, and attention to individual needs.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Treatment is tailored to each person&#x27;s circumstances and may incorporate evidence-based approaches such as Cognitive Behavioural Therapy (CBT), Acceptance and Commitment Therapy (ACT), and behavioural activation, helping clients develop practical skills to manage anxiety, improve mood, build resilience, and support long-term wellbeing.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">What support does MBP provide?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 my-8"><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Clinically informed intake</h3><p class="text-[15px] leading-relaxed text-ink/85">Fast, clinically informed intake that prepares clients for a successful therapeutic journey.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Accurate Referral Coordination</h3><p class="text-[15px] leading-relaxed text-ink/85">Medicare and referral coordination handled with accuracy and discretion.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Clear Administrative Boundaries</h3><p class="text-[15px] leading-relaxed text-ink/85">Protects the therapeutic relationship and preserves clinician objectivity.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Coordinated Care Support</h3><p class="text-[15px] leading-relaxed text-ink/85">Liaison with other health providers when appropriate, with strict confidentiality.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Practical Referral Assistance</h3><p class="text-[15px] leading-relaxed text-ink/85">Help with referrals, Medicare paperwork, and consent processes for adolescents and adults.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Flexible Access to Care</h3><p class="text-[15px] leading-relaxed text-ink/85">Access practitioners across Brisbane and via telehealth for regional and interstate clients.</p></div></div></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">How do I get started?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If you&#x27;re unsure what your teen is experiencing, please email us using the form below or contact us, and we&#x27;ll help you arrange an appointment with an experienced Brisbane psychologist or allied health professional . You may also view our Practitioner Page and select a clinician directly:</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">You may also view our Practitioner Page and select the clinician of your choice.</p><h3 class="text-2xl font-semibold mt-8 mb-3">Important safety note</h3><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If you are in immediate danger, experiencing severe distress, or having thoughts of harming yourself, contact emergency services or a crisis service right away. If you are concerned but not in immediate danger, please mention this when you contact us so we can prioritise an appropriate, timely response.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">What Is Adult Anxiety and Depression?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Anxiety and depression are among the most common mental health concerns affecting adults. While occasional stress, worry, or sadness are normal parts of life, persistent symptoms that interfere with work, relationships, or daily functioning may indicate the need for professional support.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Anxiety often involves excessive worry, fear, or nervousness that can feel difficult to control. Depression can affect mood, energy, motivation, self-esteem, and the ability to enjoy once meaningful activities. These conditions may occur separately or together and can significantly impact overall wellbeing.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">A range of factors may contribute to anxiety and depression, including genetics, life stressors, traumatic experiences, relationship difficulties, major life transitions, health concerns, and ongoing patterns of negative thinking. The good news is that both conditions are highly treatable, and evidence-based psychological therapies can help individuals understand their experiences, develop effective coping strategies, and improve their quality of life.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Common Signs and Symptoms</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Depression is more than feeling sad from time to time. It can involve a persistent low mood, a loss of interest in activities that were once enjoyable, and a noticeable reduction in energy, motivation, and enthusiasm for daily life. Individuals experiencing depression may also notice changes in sleep patterns or appetite, difficulties concentrating, and increased feelings of guilt, hopelessness, or worthlessness. Over time, these symptoms can affect relationships, work performance, and overall wellbeing, often leading to social withdrawal and a sense of disconnection from others.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Anxiety</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Anxiety can present in many ways and often involves persistent worry, excessive fear, or a sense of being overwhelmed.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">People experiencing anxiety may find it difficult to concentrate, struggle with racing thoughts, feel restless or constantly on edge, and avoid situations they perceive as stressful or threatening.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Physical symptoms are also common and may include muscle tension, headaches, stomach discomfort, increased heart rate, sweating, trembling, or other signs of heightened stress.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Depression</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Individuals experiencing depression may also notice changes in sleep patterns or appetite, difficulties concentrating, and increased feelings of guilt, hopelessness, or worthlessness.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Over time, these symptoms can affect relationships, work performance, and overall well-being, often leading to social withdrawal and a sense of disconnection from others.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">When Should I Seek Support?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">It may be helpful to seek professional support when anxiety or depression begins to interfere with your daily life, relationships, work, studies, or overall well-being. Early intervention can help reduce symptoms, strengthen coping skills, and support long-term emotional health and recovery.</p><figure class="my-9"><img src="https://michellebarrattpsychology.com.au/wp-content/uploads/2026/05/38882.jpg" alt="38882" loading="lazy" class="w-full max-w-4xl aspect-[3/2] object-cover rounded border border-lilac"/></figure><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Living through the challenges of Adult Anxiety and Depression may feel daunting, yet with the right support and techniques, families can better manage these difficulties. Whether you or a loved one is facing the effects of Adult Anxiety and Depression, we encourage you to contact Michelle Barratt Psychology for assistance.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Family Support for Living with Adult Anxiety and Depression</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Living with a family member who has anxiety and depression can be challenging and often impacts the mental health of parents, spouses, partners, and other family members. It&#x27;s common for family members to feel unsure about how to provide effective support, which can lead to feelings of anxiety, depression, and emotional exhaustion.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">At Michelle Barratt Psychology, we understand the complexities of navigating relationships with loved ones who have Anxiety and Depression and require Adult Anxiety and Therapy Brisbane.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">We offer support and guidance to families to help them understand the disorder, develop coping strategies, and foster a more supportive and understanding home environment.</p><div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 my-8"><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">1 Education</h3><p class="text-[15px] leading-relaxed text-ink/85">Helping family members understand the symptoms and underlying causes of BPD to reduce confusion and blame.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">2 Communication Skills</h3><p class="text-[15px] leading-relaxed text-ink/85">Teaching effective communication techniques to improve interactions and reduce conflicts.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">3 Boundary Setting</h3><p class="text-[15px] leading-relaxed text-ink/85">Assisting families in establishing healthy boundaries to protect their well-being while supporting their loved ones.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">4 Self-Care</h3><p class="text-[15px] leading-relaxed text-ink/85">Encouraging self-care practices for family members to maintain their mental and emotional health.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">5 Support Groups</h3><p class="text-[15px] leading-relaxed text-ink/85">Providing access to support groups where families can share experiences and learn from others in similar situations.</p></div></div></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Contact Us on the Email Form Below</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Please be advised that you&#x27;ll receive a response within 24 to 48 hours.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If in crisis, please call 000.</p></div></section><section class="bg-lilac !py-14"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-rose mb-4">More in <!-- -->Individuals &amp; Adult Therapy</p><ul class="flex flex-wrap gap-3"><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/christian-counselling">Christian Therapy<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/managing-stress">Stress Management<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/emotional-regulation">Emotional Regulation<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/trauma">Trauma<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/burnout">Burnout<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li></ul></div></section><section class="bg-blush"><div class="mx-auto max-w-4xl px-5 py-14 md:py-16 text-center"><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-rose mb-2.5">Take the first step</p><h2 class="text-[30px] md:text-[40px] font-semibold leading-[1.1]">Ready to Take the First Step?</h2><div class="h-[3px] w-14 bg-sun mt-4 mx-auto" aria-hidden="true"></div><p class="mt-5 text-[17px]">Seeking support can feel overwhelming, but you do not have to navigate life&#x27;s challenges alone. Our administration team can help answer your questions, explain appointment options and connect you with a suitable practitioner.</p><p class="mt-3">Prefer to call? Phone our administration team on <a class="text-ocean underline underline-offset-4 font-medium" href="tel:0731850040">07 3185 0040</a>.</p><div class="mt-7 flex flex-wrap justify-center gap-3"><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-rose text-white hover:bg-[#9d2a59] " href="/practitioners">Book Online</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-ocean text-white hover:bg-[#095a6f] " href="/contact">Contact Us</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 border border-plum text-plum hover:bg-lilac  active" href="/therapy-services" data-status="active" aria-current="page">Explore Services</a></div><p class="mt-5 text-sm text-ink/70">If in crisis, please call 000.</p></div></section><!--/$-->',a={title:e,description:t,html:i};export{a as default,t as description,i as html,e as title};
